        static readonly Dictionary<string,int> Index=Keys.Select((s,i)=>new {s,i}).ToDictionary(x=>x.s,x=>x.i,StringComparer.Ordinal);
        static ReviewLanguages(){for(int i=2;i<Packs.Length;i++)if(Packs[i].Length!=Keys.Length)throw new InvalidOperationException("Language vocabulary length: "+Codes[i]);foreach(var x in Extra)if(x.Value.Length!=16)throw new InvalidOperationException("Extra vocabulary length: "+x.Key);}
        internal static void Validate(int value){if(value<0||value>=Names.Length)throw new ArgumentOutOfRangeException("LanguageIndex","Expected 0..18.");}
        internal static string Text(int language,string en,string zh){Validate(language);return language==18?ReviewTraditionalChinese.Text(zh):language==0?zh:Translate(language,en);}
        internal static string Translate(int language,string text)
        {
            string localized;if(language!=0&&language!=18&&Xiongxin.OWTS.Localization.UiLanguage.TryTranslate(language,text,out localized))return localized;
            language=Xiongxin.OWTS.Localization.UiLanguage.LegacyIndex(language);
            if(language<2||language==18||String.IsNullOrEmpty(text))return text;
            string[] extra;if(Extra.TryGetValue(text,out extra))return extra[language-2];
            string alias;if(Aliases.TryGetValue(text,out alias))return Translate(language,alias);
            int k;if(Index.TryGetValue(text,out k))return Packs[language][k];
            // Only UI labels with explicit separators are compositional. Never
            // rewrite arbitrary diagnostic prose, file paths, IDs or numbers.
            string trimmed=text.Trim();if(Index.TryGetValue(trimmed,out k))return text.Substring(0,text.Length-text.TrimStart().Length)+Packs[language][k]+text.Substring(text.TrimEnd().Length);
            foreach(string separator in new[]{" / ",": "," ≥ "," ("}){int p=text.IndexOf(separator,StringComparison.Ordinal);if(p>0&&Index.TryGetValue(text.Substring(0,p),out k))return Packs[language][k]+text.Substring(p);}
            if(text=="← Prev")return "← "+Translate(language,"Prev");if(text=="Next →")return Translate(language,"Next")+" →";
            if(text=="△ Mid")return "△ "+new[]{"Ср.","Sred.","Stř.","Moy.","Mittel","Köz.","Media","Śr.","Med.","Сред.","Sred.","Str.","Sred.","Media","Orta","Vừa"}[language-2];
            if(text=="✓ High"||text=="△ Mid"||text=="⊘ Low")return text.Substring(0,2)+Translate(language,text.Substring(2));
            return text;
        }
