    public sealed partial class PdReviewControl
    {
        int languageIndex;
        readonly Dictionary<float,System.Drawing.Font> languageFonts=new Dictionary<float,System.Drawing.Font>();
        bool languageFontCleanup;
        void FitLanguageLabels()
        {
            if(!languageFontCleanup){languageFontCleanup=true;Disposed+=(s,e)=>{foreach(var f in languageFonts.Values)f.Dispose();languageFonts.Clear();};}
            var targets=new List<System.Windows.Forms.Control>();targets.AddRange(metricLabels);targets.AddRange(classIndicators);targets.AddRange(filterChoices);
            targets.Add(statisticsEnabledBox);targets.Add(highLabel);targets.Add(lowLabel);targets.Add(waveLabel);targets.Add(ignoreLabel);targets.Add(strengthLabel);
            foreach(var target in targets){float size=Font.Size;int inset=target==statisticsEnabledBox?20:4;
                System.Drawing.Font font;if(!languageFonts.TryGetValue(size,out font)){font=new System.Drawing.Font(Font.FontFamily,size,Font.Style);languageFonts.Add(size,font);}target.Font=font;
            }
        }
        int appliedLanguageIndex = -1;
        [Category("Language"),DefaultValue(0),Description("0中文 1English 2bg 3hr 4cs 5fr 6de 7hu 8it 9pl 10ro 11ru 12sr 13sk 14sl 15es 16tr 17vi 18繁體中文")]
        public int LanguageIndex
        {
            get { return languageIndex; }
            set
            {
                ReviewLanguages.Validate(value);
                // Reapplying the host context is not a language change. In
                // particular it must not rebuild the location tree or refit
                // every sidebar control when the page becomes visible again.
                if (languageIndex == value && appliedLanguageIndex == value) return;
                appliedLanguageIndex = -1;
                languageIndex = value; english = value != 0 && value != 18;
                pdmap.LanguageIndex = value; spectrum.LanguageIndex = value;
                UpdateLanguage(); RefreshNoiseReferenceUi(); RefreshReviewUi();
                appliedLanguageIndex = value;
            }
        }
        [Browsable(false)] public string[] AvailableLanguages {get{return (string[])ReviewLanguages.Names.Clone();}}
        [Browsable(false)] public string LanguageCode {get{return ReviewLanguages.Codes[languageIndex];}}
        public void SetLanguageIndex(int index){LanguageIndex=index;}
        string L(string en,string zh){return ReviewLanguages.Text(languageIndex,en,zh);}
        string[] L(string[] en,string[] zh){return ReviewLanguages.Text(languageIndex,en,zh);}
    }
